create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text, created_at timestamptz not null default now());
create table public.user_roles (user_id uuid not null references public.profiles(id) on delete cascade, role text not null check(role in ('author','reviewer','admin')), primary key(user_id,role));
create table public.reviewer_applications (id bigint generated always as identity primary key, user_id uuid not null references public.profiles(id), expertise text not null, qualifications text not null, status text not null default 'pending' check(status in ('pending','approved','rejected')), created_at timestamptz not null default now());
create table public.articles (id uuid primary key default gen_random_uuid(), submitter_id uuid not null references public.profiles(id), title text not null, abstract text not null, language_code text not null default 'ht' check(language_code='ht'), status text not null default 'draft' check(status in ('draft','submitted','under_review','revision_requested','accepted','rejected','published')), created_at timestamptz not null default now(), published_at timestamptz);
create table public.article_versions (id uuid primary key default gen_random_uuid(), article_id uuid not null references public.articles(id) on delete cascade, version_number integer not null check(version_number>0), storage_path text not null, created_at timestamptz not null default now(), unique(article_id,version_number));
create table public.review_assignments (id uuid primary key default gen_random_uuid(), article_id uuid not null references public.articles(id) on delete cascade, reviewer_id uuid not null references public.profiles(id), assigned_by uuid not null references public.profiles(id), status text not null default 'invited' check(status in ('invited','accepted','declined','completed')), assigned_at timestamptz not null default now(), unique(article_id,reviewer_id));
create table public.reviews (id uuid primary key default gen_random_uuid(), assignment_id uuid not null unique references public.review_assignments(id) on delete cascade, recommendation text not null check(recommendation in ('approve','revise','reject')), comments text not null, submitted_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.user_roles enable row level security; alter table public.reviewer_applications enable row level security; alter table public.articles enable row level security; alter table public.article_versions enable row level security; alter table public.review_assignments enable row level security; alter table public.reviews enable row level security;
create policy profiles_own_read on public.profiles for select to authenticated using (id=(select auth.uid()));
create policy profiles_own_insert on public.profiles for insert to authenticated with check (id=(select auth.uid()));
create policy profiles_own_update on public.profiles for update to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
create policy roles_own_read on public.user_roles for select to authenticated using(user_id=(select auth.uid()));
create policy applications_own_read on public.reviewer_applications for select to authenticated using(user_id=(select auth.uid()));
create policy applications_own_insert on public.reviewer_applications for insert to authenticated with check(user_id=(select auth.uid()) and status='pending');
create policy articles_public_or_own_read on public.articles for select to anon, authenticated using(status='published' or submitter_id=(select auth.uid()));
create policy articles_own_insert on public.articles for insert to authenticated with check(submitter_id=(select auth.uid()) and status='draft');
create policy versions_own_read on public.article_versions for select to authenticated using(exists(select 1 from public.articles a where a.id=article_id and a.submitter_id=(select auth.uid())));
create policy assignments_reviewer_read on public.review_assignments for select to authenticated using(reviewer_id=(select auth.uid()));
create policy reviews_reviewer_read on public.reviews for select to authenticated using(exists(select 1 from public.review_assignments ra where ra.id=assignment_id and ra.reviewer_id=(select auth.uid())));